const SPOTNAME=id=>SPOTS.find(s=>s.id===id).name;
let db=null,dbState='loading',all=[],cur=null,lastBtn=null,sketchOn=true,curK=0;
function unlocked(){
 if(location.hash==='#mo')return true;
 const d=new Date(Date.now()+7*3600*1000);
 return d.getUTCFullYear()>2026||(d.getUTCFullYear()===2026&&(d.getUTCMonth()>10||(d.getUTCMonth()===10&&d.getUTCDate()>=19)));
}
function rows(snap){
 const out=[];
 const push=d=>{const v=(d&&typeof d.data==='function')?d.data():d;if(v&&v.to)out.push(Object.assign({id:d&&d.id},v))};
 if(Array.isArray(snap))snap.forEach(push);
 else if(snap&&snap.docs)snap.docs.forEach(push);
 else if(snap&&typeof snap.forEach==='function')snap.forEach(push);
 return out;
}
const $=id=>document.getElementById(id);
function screen(n){if(n!=='s-game')leavePosSafe();
 ['s-start','s-write','s-game'].forEach(x=>$(x).classList.toggle('show',x===n));if(n!=='s-game')running=false}
function mkPick(box,cb){
 box.textContent='';
 PEOPLE.forEach((p,i)=>{
  const b=document.createElement('button');b.type='button';b.className='pk';
  b.innerHTML='<img alt="" src="'+SPR[p.id]+'"><b>'+p.name+'</b><small>Bấm để chọn</small>';
  b.addEventListener('click',()=>cb(i,b));box.appendChild(b);
 });
}
mkPick($('pick'),i=>startGame(i));
(function(){
 const box=document.createElement('div');box.className='pick';box.id='pickg';
 const t=document.createElement('p');t.className='lead';t.textContent='Hoặc vào chạy chung (không có clue):';
 const sp=$('s-start');sp.insertBefore(t,sp.querySelector('.alt'));sp.insertBefore(box,sp.querySelector('.alt'));
 GUESTS.forEach((g,j)=>{const b=document.createElement('button');b.type='button';b.className='pk';b.innerHTML='<img alt="" src="'+SPR[g.id]+'"><b>'+g.name+'</b><small>Chạy chung</small>';b.addEventListener('click',()=>startGame(PEOPLE.length+j));box.appendChild(b)});
})();
mkPick($('pick2'),(i,b)=>openProfile(i,b));
$('btn-write').addEventListener('click',()=>screen('s-write'));
$('back1').addEventListener('click',()=>screen('s-start'));
$('back2').addEventListener('click',()=>screen('s-start'));

/* ---------- profile modal: photos, wishes, form ---------- */
function renderWishes(){
 const p=PEOPLE[cur],box=$('wlist');box.textContent='';
 const mine=all.filter(w=>w.to===p.id).sort((a,b)=>(a.at||0)-(b.at||0));
 const note=txt=>{const d=document.createElement('div');d.className='note';d.textContent=txt;box.appendChild(d)};
 if(dbState==='loading'){note('Đang tải lời chúc...');return}
 if(dbState!=='ready'){note('Chưa kết nối được kho lời chúc. Bạn thử tải lại trang nhé.');return}
 if(!unlocked()){const n=counts[p.id]||0;note(n?'Đã có '+n+' lời chúc dành cho '+p.name+'. Lời chúc sẽ mở vào ngày 19.11, hãy quay lại nhé!':'Chưa có lời chúc nào cho '+p.name+(PLAYER_DONE?'.':'. Bạn hãy là người đầu tiên!'));return}
 if(!mine.length){note('Chưa có lời chúc nào cho '+p.name+'.');return}
 mine.forEach(w=>{const d=document.createElement('div');d.className='wish';const m=document.createElement('div');m.className='m';m.textContent=w.text;const f=document.createElement('div');f.className='f';f.textContent='// '+(w.from||'Một người bạn');d.appendChild(m);d.appendChild(f);box.appendChild(d)});
}
let PLAYER_DONE=false;
function show(p,k){
 curK=k;
 const it=p.items[k],m=$('mimg'),v=$('mvid'),t=$('tog');
 v.pause();
 if(it.t==='v'){m.hidden=true;v.hidden=false;v.src=it.s;v.poster=it.p||'';t.hidden=true}
 else{v.hidden=true;v.removeAttribute('src');v.load();m.hidden=false;m.src=(k===0&&sketchOn)?p.sketch:it.s;m.alt='Ảnh '+p.name;
  if(k===0){t.hidden=false;t.innerHTML=ICON('i-pen')+' '+(sketchOn?'Xem ảnh màu':'Xem tranh nét')}else t.hidden=true}
 document.querySelectorAll('#thumbs button').forEach((x,j)=>x.setAttribute('aria-pressed',j===k?'true':'false'));
}
$('tog').addEventListener('click',()=>{sketchOn=!sketchOn;if(cur!==null)show(PEOPLE[cur],0)});
function openProfile(i,btn,done){
 const p=PEOPLE[i];lastBtn=btn||null;cur=i;sketchOn=true;PLAYER_DONE=!!done;
 const th=$('thumbs');th.innerHTML='';
 const list=done?p.items:p.items;
 if(p.items.length>1)p.items.forEach((it,k)=>{const x=document.createElement('button');x.type='button';x.setAttribute('aria-label',(it.t==='v'?'Xem clip của ':'Xem ảnh '+(k+1)+' của ')+p.name);x.innerHTML='<img alt="" src="'+(it.t==='v'?it.p:(k===0?p.sketch:it.s))+'">'+(it.t==='v'?'<span class="pl">'+ICON('i-play')+'</span>':'');x.addEventListener('click',()=>show(p,k));th.appendChild(x)});
 show(p,0);
 $('mfile').textContent='~/'+p.id+'.js';
 $('mt').textContent=p.name;$('mtag').textContent=p.tag;
 $('wmsg').textContent='';
 try{const n=localStorage.getItem('wname');if(n&&!$('wname').value)$('wname').value=n}catch(e){}
 renderWishes();loadWishes();
 $('overlay').classList.add('show');$('close').focus();
}
function closeProfile(){$('mvid').pause();$('overlay').classList.remove('show');cur=null;if(lastBtn&&lastBtn.focus)lastBtn.focus()}
$('close').addEventListener('click',closeProfile);
$('overlay').addEventListener('click',e=>{if(e.target===$('overlay'))closeProfile()});
$('wform').addEventListener('submit',async e=>{
 e.preventDefault();
 const msg=$('wmsg'),btn=$('wsend');
 const name=$('wname').value.trim(),text=$('wtext').value.trim();
 if(!name||!text||cur===null)return;
 if(!sb){msg.textContent='Chưa kết nối được kho lời chúc. Bạn thử tải lại trang nhé.';return}
 btn.disabled=true;msg.textContent='Đang gửi...';
 const p=PEOPLE[cur];
 try{
  const r=await sb.from('wishes').insert({to_id:p.id,from_name:name,text:text});
  if(r.error)throw r.error;
  try{localStorage.setItem('wname',name)}catch(e){}
  $('wtext').value='';msg.textContent='Đã gửi! Cảm ơn bạn, bạn có thể viết thêm.';confetti();
  counts[p.id]=(counts[p.id]||0)+1;if(cur!==null)renderWishes();
 }catch(err){msg.textContent='Chưa gửi được. Bạn thử lại sau ít phút nhé.'}
 btn.disabled=false;
});

/* ---------- game ---------- */
const cv=$('g'),cx=cv.getContext('2d');
const W=cv.width,H=cv.height;
let me=0,clueIdx=0,wrong=0,visited={},running=false,last=0,keys={},target=null,near=null,hintUntil=0,toastT=null,CLUELIST=[];
const player={x:400,y:360,face:1,moving:false};
const avatar={};Object.keys(SPR).forEach(k=>{const im=new Image();im.src=SPR[k];avatar[k]=im});
function toast(t){$('toast').textContent=t;clearTimeout(toastT);toastT=setTimeout(()=>{if($('toast').textContent===t)$('toast').textContent=''},5000)}
function key(){return 'hunt-'+PEOPLE[me].id}
function startGame(i){
 const clueEl=document.querySelector('#s-game .clue');
 if(i>=PEOPLE.length){
  GUEST=true;me=i;CLUELIST=[];clueIdx=0;visited={};target=null;
  player.x=400;player.y=360;screen('s-game');
  clueEl.style.display='none';if($('chk'))$('chk').style.display='none';$('act').style.display='none';
  toast('Bạn đang chạy chung trong văn phòng, không có clue.');
  running=true;last=performance.now();requestAnimationFrame(loop);return;
 }
 GUEST=false;clueEl.style.display='';if($('chk'))$('chk').style.display='';$('act').style.display='';
 me=i;CLUELIST=CLUES[PEOPLE[i].id];clueIdx=0;wrong=0;visited={};target=null;
 try{const v=parseInt(localStorage.getItem(key()),10);if(v>0&&v<=CLUELIST.length){clueIdx=v;CLUELIST.slice(0,v).forEach(c=>visited[c.spot]=true)}}catch(e){}
 player.x=400;player.y=360;
 screen('s-game');setClue();running=true;last=performance.now();requestAnimationFrame(loop);
 if(clueIdx>=CLUELIST.length)finish();
}
function updateList(){
 let el=$('chk');
 if(!el){el=document.createElement('div');el.id='chk';el.style.cssText='margin:10px 0 0;padding:10px 12px;background:rgba(24,20,44,.76);border:2px solid #ffd27a;border-radius:12px;font-weight:800;font-size:14px';document.querySelector('#s-game .gbar').before(el)}
 const L=CLUELIST,p=PEOPLE[me];
 const lab=c=>{if(c.perk)return '1 phúc lợi';const n=c.items.length,v=c.items.filter(k=>p.items[k].t==='v').length,ph=n-v;const a=[];if(ph)a.push(ph+' ảnh');if(v)a.push(v+' clip');return a.join(' + ')};
 el.textContent='';
 const h=document.createElement('div');h.style.cssText='color:#ffd27a;margin-bottom:6px';
 const totalItems=L.reduce((t,c)=>t+(c.perk?1:c.items.length),0);
 h.textContent='Đã tìm '+Math.min(clueIdx,L.length)+'/'+L.length+' manh mối (tổng '+totalItems+' mục: ảnh, clip và phúc lợi)';el.appendChild(h);
 const row=document.createElement('div');row.style.cssText='display:flex;flex-wrap:wrap;gap:6px';
 L.forEach((c,i)=>{const b=document.createElement('span');const d=i<clueIdx;b.textContent=(d?'✓ ':'○ ')+(i+1)+'. '+lab(c);b.style.cssText='padding:4px 10px;border-radius:999px;font-size:13px;'+(d?'background:#8fcf7e;color:#1d1b2e':'background:rgba(255,255,255,.1);color:#f3ecda');row.appendChild(b)});
 el.appendChild(row);
}
let hintOpen=false;
function renderHint(){
 const done=clueIdx>=CLUELIST.length;
 let bt=$('hbtn');
 if(!bt){bt=document.createElement('button');bt.id='hbtn';bt.type='button';bt.className='ghost';bt.style.cssText='margin-top:8px;padding:8px 16px;font-size:14px';bt.addEventListener('click',()=>{hintOpen=!hintOpen;renderHint()});$('clue-t').after(bt)}
 if(done){bt.hidden=true;$('clue-t').textContent='Bạn đã tìm đủ. Mở hồ sơ để xem lời chúc.';return}
 bt.hidden=false;
 if(hintOpen){$('clue-t').textContent=CLUELIST[clueIdx].text;bt.textContent='Ẩn gợi ý'}
 else{$('clue-t').textContent='Hãy chạy quanh văn phòng và khám phá các điểm. Cần giúp thì bấm "Xem gợi ý".';bt.textContent='Xem gợi ý'}
}
function setClue(){
 updateList();hintOpen=false;
 if(clueIdx>=CLUELIST.length){$('clue-k').textContent='// hoàn thành';renderHint();return}
 $('clue-k').textContent='$ manh_moi['+(clueIdx+1)+'/'+CLUELIST.length+']';
 renderHint();
}
function explore(){
 if(GUEST)return;
 if(!near||clueIdx>=CLUELIST.length){if(clueIdx>=CLUELIST.length)finish();else toast('Hãy lại gần một địa điểm trên bản đồ rồi bấm Khám phá.');return}
 const c=CLUELIST[clueIdx];
 if(near.id===c.spot){
  visited[near.id]=true;wrong=0;
  const its=c.perk?[c.perk]:c.items.map(k=>PEOPLE[me].items[k]);
  clueIdx++;try{localStorage.setItem(key(),String(clueIdx))}catch(e){}
  showFound(near,its,clueIdx>=CLUELIST.length);confetti();
 }else{
  wrong++;
  toast(wrong>=2?'Chưa phải chỗ này. Mình đã đánh dấu gợi ý trên bản đồ, hãy nhìn vòng sáng nhấp nháy.':'Chưa phải chỗ này, thử đọc lại manh mối nhé!');
  if(wrong>=2)hintUntil=performance.now()+6000;
 }
}
function showFound(spot,items,lastOne){
 $('ft').textContent='Tìm thấy rồi! '+spot.name;
 $('fp').textContent=items[0]&&items[0].t==='p'?'Bạn nhận được một phúc lợi!':(items.length>1?'Bạn tìm được '+items.length+' mục ở đây.':'Bạn tìm được một mục ở đây.');
 const box=$('fm');box.textContent='';
 items.forEach(it=>{
  if(it.t==='p'){const d=document.createElement('div');d.style.cssText='background:#ffd27a;color:#1d1b2e;border:3px dashed #1d1b2e;border-radius:14px;padding:16px 18px;text-align:center;font-weight:800;width:100%';d.innerHTML='<div style="font-size:40px"></div><div style="font-size:20px;font-weight:900;margin-top:4px"></div><div style="font-size:13px;margin-top:6px"></div><div style="font-size:12px;margin-top:8px;font-weight:700">Chụp màn hình thẻ này để dùng phúc lợi.</div>';const ch=d.children;ch[0].textContent=it.ico;ch[1].textContent=it.title;ch[2].textContent=it.valid;box.appendChild(d)}
  else if(it.t==='v'){const v=document.createElement('video');v.controls=true;v.playsInline=true;v.preload='metadata';v.src=it.s;if(it.p)v.poster=it.p;box.appendChild(v)}
  else{const im=document.createElement('img');im.src=it.s;im.alt='Ảnh tìm thấy';box.appendChild(im)}
 });
 $('fnext').textContent=lastOne?'Mở hồ sơ và lời chúc':'Tiếp tục';
 $('fnext').dataset.last=lastOne?'1':'';
 $('found').classList.add('show');$('fnext').focus();
}
$('fnext').addEventListener('click',()=>{
 document.querySelectorAll('#fm video').forEach(v=>v.pause());
 $('found').classList.remove('show');
 if($('fnext').dataset.last){finish()}else setClue();
});
function finish(){setClue();openProfile(me,$('act'),true)}
$('act').addEventListener('click',explore);
document.addEventListener('keydown',e=>{
 if($('overlay').classList.contains('show')||$('found').classList.contains('show')){if(e.key==='Escape'){if($('overlay').classList.contains('show'))closeProfile()}return}
 const k=e.key.toLowerCase();
 if(['arrowup','arrowdown','arrowleft','arrowright','w','a','s','d'].includes(k)&&running){keys[k]=true;target=null;e.preventDefault()}
 if((k===' '||k==='enter')&&running&&document.activeElement===document.body){e.preventDefault();explore()}
});
