function loop(now){
 if(!running)return;
 const dt=Math.min(0.05,(now-last)/1000);last=now;
 let dx=0,dy=0;
 if(keys.arrowleft||keys.a)dx-=1;if(keys.arrowright||keys.d)dx+=1;if(keys.arrowup||keys.w)dy-=1;if(keys.arrowdown||keys.s)dy+=1;
 if(dx||dy){const l=Math.hypot(dx,dy);dx/=l;dy/=l}
 else if(target){const tx=target.x-player.x,ty=target.y-player.y,l=Math.hypot(tx,ty);if(l>4){dx=tx/l;dy=ty/l}else target=null}
 player.x=Math.max(26,Math.min(W-26,player.x+dx*190*dt));
 player.y=Math.max(130,Math.min(H-26,player.y+dy*190*dt));
 if(dx)player.face=dx>0?1:-1;player.moving=!!(dx||dy);sendPresence(now);
 near=null;let nd=1e9;
 SPOTS.forEach(s=>{const d=Math.hypot(s.x-player.x,s.y-player.y);if(d<RAD&&d<nd){nd=d;near=s}});
 $('act').disabled=!near&&clueIdx<CLUELIST.length;
 $('act').textContent=clueIdx>=CLUELIST.length?'Mở hồ sơ':(near?'Khám phá: '+near.name:'Khám phá');
 draw(now);requestAnimationFrame(loop);
}
