const NPC=CAST.map((p,i)=>{const h=[[300,330],[500,330],[250,390],[560,390],[450,200],[330,300],[600,380]][i%7];return {x:h[0],y:h[1],tx:h[0],ty:h[1],w:0,f:1,hx:h[0],hy:h[1]}});
function npcStep(o,now,dt){
 if(now>o.w){o.w=now+2500+Math.random()*4000;if(Math.random()<.6){o.tx=Math.max(40,Math.min(W-40,o.hx+(Math.random()-.5)*200));o.ty=Math.max(150,Math.min(H-40,o.hy+(Math.random()-.5)*120))}}
 const dx=o.tx-o.x,dy=o.ty-o.y,l=Math.hypot(dx,dy);o.mv=l>3;
 if(o.mv){o.x+=dx/l*55*dt;o.y+=dy/l*55*dt;o.f=dx>0?1:-1}
}
const PE={};let room=null,lastSend=0,online=[];
let lastSig='',lastW=0,sb=null,chan=null,netOK=false,counts={};
function sendPresence(now){
 if(!chan||!netOK||!running)return;
 const sig=Math.round(player.x/4)+','+Math.round(player.y/4)+','+player.face+','+(player.moving?1:0);
 if(sig===lastSig&&now-lastW<2000)return;
 if(now-lastW<333)return;
 lastSig=sig;lastW=now;
 try{chan.send({type:'broadcast',event:'pos',payload:{id:MYID,pi:me,name:CAST[me].name,x:Math.round(player.x),y:Math.round(player.y),f:player.face,m:player.moving?1:0,n:Math.floor(now)}})}catch(e){}
}
function leavePos(){if(chan&&netOK){try{chan.send({type:'broadcast',event:'bye',payload:{id:MYID}})}catch(e){}}lastSig='';lastW=0}
addEventListener('pagehide',leavePos);
const MYID=(()=>{let v='';try{v=localStorage.getItem('pid')||''}catch(e){}if(!v){v='p'+Math.random().toString(36).slice(2,9);try{localStorage.setItem('pid',v)}catch(e){}}return v})();
function leavePosSafe(){try{leavePos()}catch(e){}}
const DBPOS={};
function handlePos(v){
 if(!v||!v.id||v.id===MYID||typeof v.x!=='number'||typeof v.y!=='number'||typeof v.pi!=='number'||!CAST[v.pi])return;
 const o=DBPOS[v.id]||(DBPOS[v.id]={x:v.x,y:v.y,seen:0,n:-1});
 o.seen=Date.now();o.n=v.n;o.tx=v.x;o.ty=v.y;o.pi=v.pi;o.name=String(v.name||'').slice(0,16);o.f=v.f<0?-1:1;o.m=v.m?1:0;
}
function syncPeers(){
 const now=Date.now();
 Object.keys(DBPOS).forEach(k=>{
  const o=DBPOS[k];
  if(now-o.seen>9000){delete PE[k];return}
  const e=PE[k]||(PE[k]={x:o.x,y:o.y});
  e.tx=o.tx;e.ty=o.ty;e.pi=o.pi;e.name=o.name;e.f=o.f;e.m=o.m;
 });
 Object.keys(PE).forEach(k=>{if(!DBPOS[k]||now-DBPOS[k].seen>9000)delete PE[k]});
}
function drawChar(id,x,y,face,moving,now,name,isMe){
 const im=avatar[id];if(!im||!im.complete||!im.naturalWidth)return;
 const bob=moving?Math.abs(Math.sin(now/90))*4:Math.sin(now/500)*1;
 cx.fillStyle='rgba(20,10,30,.35)';cx.beginPath();cx.ellipse(x,y+9,15,5,0,0,7);cx.fill();
 cx.save();cx.imageSmoothingEnabled=false;cx.translate(x,y-46-bob);
 if(face<0){cx.translate(40,0);cx.scale(-1,1)}
 cx.drawImage(im,0,0,40,55);cx.restore();
 if(name){
  cx.font='800 13px Nunito,"Be Vietnam Pro",sans-serif';cx.textAlign='center';
  const tw=cx.measureText(name).width+16;
  rr(x-tw/2,y-76-bob,tw,20,10,isMe?'rgba(242,180,90,.92)':'rgba(24,20,44,.8)');
  cx.fillStyle=isMe?'#1d1b2e':'#f3ecda';cx.fillText(name,x,y-62-bob);
 }
}
function draw(now){
 cx.imageSmoothingEnabled=false;
 cx.clearRect(0,0,W,H);cx.drawImage(SC,0,0,W,H);
 const g=cx.createLinearGradient(0,0,0,H);g.addColorStop(0,'rgba(255,170,90,.14)');g.addColorStop(1,'rgba(50,30,100,.22)');
 cx.fillStyle=g;cx.fillRect(0,0,W,H);
 cx.font='800 13px Nunito,"Be Vietnam Pro",sans-serif';cx.textAlign='center';
 SPOTS.forEach(s=>{
  if(visited[s.id]){circ(s.x,s.y-30,11,'#8fcf7e');cx.strokeStyle='#1d1b2e';cx.lineWidth=3;cx.beginPath();cx.moveTo(s.x-5,s.y-30);cx.lineTo(s.x-1,s.y-25);cx.lineTo(s.x+6,s.y-35);cx.stroke()}
 });
 if(now<hintUntil&&clueIdx<CLUELIST.length){const s=SPOTS.find(z=>z.id===CLUELIST[clueIdx].spot);const r=RAD-6+Math.sin(now/150)*8;cx.lineWidth=4;circ(s.x,s.y,r,null,'#ffd27a')}
 if(near){cx.lineWidth=2;circ(near.x,near.y,RAD,null,'rgba(255,210,122,.85)')}
 syncPeers();
 const live={};Object.keys(PE).forEach(k=>live[PE[k].pi]=1);
 const ents=[{y:player.y,me:1}];
 CAST.forEach((p,i)=>{if(i===me||live[i])return;const o=NPC[i];npcStep(o,now,0.016);ents.push({y:o.y,n:i,o:o})});
 Object.keys(PE).forEach(k=>{const o=PE[k];o.x+=(o.tx-o.x)*0.12;o.y+=(o.ty-o.y)*0.12;ents.push({y:o.y,o:o})});
 ents.sort((a,b)=>a.y-b.y).forEach(e=>{
  if(e.n!==undefined){const p=CAST[e.n];drawChar(p.id,e.o.x,e.o.y,e.o.f,e.o.mv,now,p.name,false)}
  else if(e.me)drawChar(CAST[me].id,player.x,player.y,player.face,player.moving,now,CAST[me].name,true);
  else{const o=e.o,p=CAST[o.pi];if(p)drawChar(p.id,o.x,o.y,o.f,(o.m||Math.hypot(o.tx-o.x,o.ty-o.y)>6),now,o.name||p.name,false)}
 });
 // online HUD
 const n=1+Object.keys(PE).length;
 cx.font='800 13px Nunito,"Be Vietnam Pro",sans-serif';cx.textAlign='left';
 const t=(netOK?'Đang trong văn phòng: ':(sb?'Đang kết nối...  ':'Chơi một mình: '))+n;const tw=cx.measureText(t).width+18;
 rr(10,10,tw,24,12,'rgba(24,20,44,.78)');cx.fillStyle='#ffd27a';cx.fillText(t,19,27);
}

/* ---------- confetti + db ---------- */
const fx=$('fx'),fc=fx.getContext('2d');
function confetti(){
 if(reduce)return;
 fx.width=innerWidth;fx.height=innerHeight;
 const cols=['#3F51B5','#3A9D93','#2BA36B','#C79BB8','#FFFFFF'];
 const ps=Array.from({length:90},()=>({x:innerWidth/2,y:innerHeight*0.4,vx:(Math.random()-0.5)*12,vy:-Math.random()*12-4,s:Math.random()*8+4,c:cols[Math.floor(Math.random()*cols.length)],r:Math.random()*6}));
 let f=0;(function tick(){
  fc.clearRect(0,0,fx.width,fx.height);
  ps.forEach(q=>{q.x+=q.vx;q.y+=q.vy;q.vy+=0.35;q.r+=0.2;fc.save();fc.translate(q.x,q.y);fc.rotate(q.r);fc.fillStyle=q.c;fc.fillRect(-q.s/2,-q.s/2,q.s,q.s*0.6);fc.restore()});
  if(++f<110)requestAnimationFrame(tick);else fc.clearRect(0,0,fx.width,fx.height);
 })();
}
async function loadWishes(){
 if(!sb)return;
 try{
  const r=await sb.from('wishes').select('id,to_id,from_name,text,created_at').order('created_at');
  if(r.error)throw r.error;
  all=(r.data||[]).map(w=>({id:w.id,to:w.to_id,from:w.from_name,text:w.text,at:Date.parse(w.created_at)}));
  const c=await sb.rpc('wish_count');counts={};(c.data||[]).forEach(x=>counts[x.to_id]=Number(x.n));
  dbState='ready';
 }catch(e){dbState='error'}
 if(cur!==null)renderWishes();
}
(async()=>{
 const cfg=window.APP_CONFIG||{};
 if(!cfg.SUPABASE_URL||!window.supabase){dbState='error';return}
 try{
  sb=window.supabase.createClient(cfg.SUPABASE_URL,cfg.SUPABASE_ANON_KEY);
  chan=sb.channel('office',{config:{broadcast:{self:false}}});
  chan.on('broadcast',{event:'pos'},m=>handlePos(m.payload)).on('broadcast',{event:'bye'},m=>{if(m&&m.payload)delete DBPOS[m.payload.id]}).subscribe(st=>{netOK=(st==='SUBSCRIBED')});
  await loadWishes();
 }catch(e){dbState='error'}
})();
